param([int]$Port = 9480,[switch]$BaselineOnly)
$ErrorActionPreference='Stop'
$edge='C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe'
$mysql='C:\xampp\mysql\bin\mysql.exe'
$profile=Join-Path $env:TEMP "curdun-p148-b4-$Port"
$url='http://localhost:8000/app.html'

function Set-ExtraSecurity([string]$json) {
  $hex=([BitConverter]::ToString([Text.Encoding]::UTF8.GetBytes($json))).Replace('-','')
  & $mysql -uroot curdun_erp -e "UPDATE settings s SET s.value=CONVERT(0x$hex USING utf8mb4),s.type='json' WHERE s.company_id=2 AND s.key='pos.extra_security'" | Out-Null
}

function Invoke-Cdp([string]$script) {
  $proc=Start-Process $edge -ArgumentList @('--headless','--disable-gpu','--disable-extensions','--no-first-run','--remote-allow-origins=*',"--remote-debugging-port=$Port","--user-data-dir=$profile",$url) -WindowStyle Hidden -PassThru
  $ws=$null
  try {
    $page=$null;for($i=0;$i -lt 60 -and !$page;$i++){Start-Sleep -Milliseconds 200;try{foreach($candidate in (Invoke-RestMethod "http://localhost:$Port/json/list")){if($candidate.type -eq 'page' -and $candidate.url -like 'http://localhost:8000/*'){$page=$candidate;break}}}catch{}}
    if(!$page){throw 'No browser page.'}
    $ws=[Net.WebSockets.ClientWebSocket]::new();$ws.ConnectAsync([Uri]$page.webSocketDebuggerUrl,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null
    $msg=@{id=1;method='Runtime.evaluate';params=@{expression=$script;awaitPromise=$true;returnByValue=$true}}|ConvertTo-Json -Depth 8 -Compress
    $bytes=[Text.Encoding]::UTF8.GetBytes($msg);$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,[Threading.CancellationToken]::None).GetAwaiter().GetResult()|Out-Null
    while($true){$buf=New-Object byte[] 1048576;$recv=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),[Threading.CancellationToken]::None).GetAwaiter().GetResult();$response=([Text.Encoding]::UTF8.GetString($buf,0,$recv.Count)|ConvertFrom-Json);if($response.id -eq 1){if($response.result.exceptionDetails){throw($response.result.exceptionDetails|ConvertTo-Json -Depth 8)};return $response.result.result.value}}
  } finally {if($ws){$ws.Dispose()};if($proc -and !$proc.HasExited){Stop-Process $proc.Id -Force}}
}

$common=@'
 const alerts=[];window.alert=message=>alerts.push(String(message));const wait=async(fn,label)=>{for(let i=0;i<160;i++){const value=fn();if(value)return value;await new Promise(r=>setTimeout(r,100));}throw new Error('Timeout '+label+' alerts='+JSON.stringify(alerts))};
 const pause=ms=>new Promise(r=>setTimeout(r,ms));const fill=(el,value)=>{el.value=value;el.dispatchEvent(new Event('input',{bubbles:true}))};
 const api=async(path,method='GET',body,approvalId)=>{const response=await fetch('/api/v1'+path,{method,credentials:'include',headers:{'Content-Type':'application/json',...(approvalId?{'X-Manager-Approval-ID':String(approvalId)}:{})},body:body===undefined?undefined:JSON.stringify(body)});let data=null;try{data=await response.json()}catch(_){}return{status:response.status,data:data?.data,message:data?.message||null,raw:data}};
 const enter=async(userId,pin)=>{const entry=await wait(()=>document.querySelector('#login-email')||document.querySelector('[data-launch="pos"]')||document.querySelector('#btn-topnav-user')||document.querySelector('[data-login-id]'),'account');if(entry.id==='login-email'){fill(entry,'fartun@shifo.so');fill(document.querySelector('#login-pw'),'Pos@1234Secure');document.querySelector('#btn-signin').click();await wait(()=>document.querySelector('[data-launch="pos"]'),'workspace')}const launch=document.querySelector('[data-launch="pos"]');if(launch)launch.click();if(!document.querySelector('[data-login-id]')){const retail=await wait(()=>document.querySelector('[data-store-type="retail"]')||document.querySelector('#btn-topnav-user'),'POS');if(retail.matches?.('[data-store-type]'))retail.click();await wait(()=>document.querySelector('#btn-topnav-user'),'nav')}if(S.posActiveUser){await posLockRegister();await wait(()=>!S.posActiveUser,'locked')}await pause(600);(await wait(()=>document.querySelector('[data-login-id="'+userId+'"]'),'staff card')).click();await pause(250);for(const digit of pin){(await wait(()=>document.querySelector('[data-key="'+digit+'"]'),'PIN key')).click();await pause(120)}await wait(()=>S.posActiveUser?.id===userId,'PIN')};
 const openRefund=async ref=>{S.posView='backoffice';S.posBackofficeTab='orders';render();await pause(350);const button=await wait(()=>document.querySelector('[data-refund-txn="'+ref+'"]'),'refund '+ref);button.click();await wait(()=>document.querySelector('.pos-refund-qty'),'refund modal');await pause(300);const qty=document.querySelector('.pos-refund-qty');fill(qty,'1');await pause(300);document.querySelector('.pos-refund-add-method[data-add-method="Cash"]').click();const submit=await wait(()=>{const el=document.querySelector('#btn-refund-submit');return el&&!el.disabled&&el.dataset.posWired==='1'?el:null},'wired refund validate');submit.click();};
'@

