 const cashierScopeId=await approve('cash-out','pos_session',31,0.2,31);document.querySelector('#btn-topnav-user').click();await wait(()=>document.querySelector('#btn-bo-lock'),'cashier switch lock');await pause(250);document.querySelector('#btn-bo-lock').click();await wait(()=>!S.posActiveUser,'cashier switch');await enter(6,'3456');const differentCashier=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.2,reason:'scope cashier'},cashierScopeId);document.querySelector('#btn-topnav-user').click();await wait(()=>document.querySelector('#btn-bo-lock'),'return lock');await pause(250);document.querySelector('#btn-bo-lock').click();await wait(()=>!S.posActiveUser,'return switch');await enter(3,'1234');
 const expiryId=await approve('cash-out','pos_session',31,0.2,31);
 S.posView='backoffice';S.posBackofficeTab='sessions';render();await pause(350);document.querySelector('#btn-cash-out').click();await wait(()=>document.querySelector('#rc-cash-amount'),'protected cash out');await pause(250);fill(document.querySelector('#rc-cash-amount'),'1');fill(document.querySelector('#rc-cash-reason'),'B4 supplies');document.querySelector('#rc-cash-submit').click();await wait(()=>S.posRegisterModal?.mode==='manager-approval','cash out approval');await pause(250);fill(document.querySelector('#rc-mgr-pin'),'3456');fill(document.querySelector('#rc-mgr-reason'),'B4 supplies approved');document.querySelector('#rc-mgr-submit').click();await wait(()=>!S.posRegisterModal,'approved cash out');const after=(await api('/pos/sessions/31/summary')).data;return{txBefore,cancelText,cancel,wrong,refund,reuse,scope:{differentAction,differentTarget,differentAmount,differentSession,differentCashier},expiryId,cashOut:{cashier:S.posActiveUser.name,expectedDelta:Number(after.expected_cash)-Number(before.expected_cash)},domSecrets:/approval_token|token_prefix|manager pin:\s*\d/i.test(document.documentElement.innerHTML)};})()"

