$success="(async()=>{`n$common`n await enter(3,'1234');let captured=null;const verify=posVerifyManagerPin;posVerifyManagerPin=async(...args)=>{captured=await verify(...args);return captured};const before=(await api('/pos/sessions/31/summary')).data;await openRefund('POS-20260822-01-000175');await wait(()=>S.posRegisterModal?.mode==='manager-approval','success modal');await pause(300);fill(document.querySelector('#rc-mgr-pin'),'3456');fill(document.querySelector('#rc-mgr-reason'),'B4 exact approved refund');document.querySelector('#rc-mgr-submit').click();await wait(()=>S.posReceiptVisible&&S.posLastReceipt?.isRefund,'success receipt');const refund={reference:S.posLastReceipt.id,cashier:S.posActiveUser.name,approvalId:Number(captured.approval.approval_id),approvedBy:captured.approved_by,response:captured};const reuse=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.2,reason:'reuse'},refund.approvalId);const approve=async(action,targetType,targetId,amount,sessionId)=>Number((await verify('3456',action,'B4 scope',S.posActiveUser.branchId,{targetType,targetId,amount,sessionId})).approval.approval_id);const actionId=await approve('refund','order',189,0.2,31);const differentAction=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.2,reason:'action'},actionId);const targetId=await approve('cash-out','pos_session',999,0.2,31);const differentTarget=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.2,reason:'target'},targetId);const amountId=await approve('cash-out','pos_session',31,0.2,31);const differentAmount=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.3,reason:'amount'},amountId);const sessionId=await approve('cash-out','pos_session',31,0.2,999);const differentSession=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.2,reason:'session'},sessionId);const cashierId=await approve('cash-out','pos_session',31,0.2,31);await posLockRegister();await enter(6,'3456');const differentCashier=await api('/pos/sessions/31/cash-movements','POST',{idempotency_key:crypto.randomUUID(),type:'OUT',amount:0.2,reason:'cashier'},cashierId);await posLockRegister();await enter(3,'1234');const expiryId=await approve('cash-out','pos_session',31,0.2,31);S.posView='backoffice';S.posBackofficeTab='sessions';render();await pause(350);document.querySelector('#btn-cash-out').click();await wait(()=>document.querySelector('#rc-cash-amount'),'cash modal');await pause(300);fill(document.querySelector('#rc-cash-amount'),'1');fill(document.querySelector('#rc-cash-reason'),'B4 supplies');wireRegisterModal();document.querySelector('#rc-cash-submit').click();await wait(()=>S.posRegisterModal?.mode==='manager-approval','cash approval');await pause(300);fill(document.querySelector('#rc-mgr-pin'),'3456');fill(document.querySelector('#rc-mgr-reason'),'B4 supplies approved');document.querySelector('#rc-mgr-submit').click();await wait(()=>!S.posRegisterModal,'cash success');const after=(await api('/pos/sessions/31/summary')).data;return{refund,reuse,scope:{differentAction,differentTarget,differentAmount,differentSession,differentCashier},expiryId,cashOut:{cashier:S.posActiveUser.name,delta:Number(after.expected_cash)-Number(before.expected_cash)},domSecrets:/approval_token|token_prefix|manager pin:\s*\d/i.test(document.documentElement.innerHTML)};})()"

