$originalSetting=& $mysql -uroot curdun_erp -N -e "SELECT value FROM settings s WHERE s.company_id=2 AND s.key='pos.extra_security' LIMIT 1"
try {
  Set-ExtraSecurity '{"refund":false,"cash_out":false,"variance_above":null,"credit_over_limit_strict":false}'
  $off=Invoke-Cdp $baseline
  if($BaselineOnly){$off|ConvertTo-Json -Depth 10;return}
  Set-ExtraSecurity '{"refund":true,"cash_out":true,"variance_above":null,"credit_over_limit_strict":false}'
  $denied=Invoke-Cdp $cancelWrong
  $on=Invoke-Cdp $success
  & $mysql -uroot curdun_erp -e "UPDATE pos_manager_approvals SET expires_at=DATE_SUB(NOW(),INTERVAL 1 SECOND) WHERE id=$($on.expiryId)" | Out-Null
  $expired=Invoke-Cdp ($expiry.Replace('__APPROVAL_ID__',[string]$on.expiryId))
  if($off.managerModal -or [math]::Abs([double]$off.cashOutDelta+0.1)-gt 0.001){throw 'Extra Security OFF baseline failed.'}
  if(!$denied.cancel.preserved -or $denied.cancel.count -ne $denied.count){throw 'Approval cancellation changed the operation.'}
  if($denied.wrong.count -ne $denied.count -or $denied.wrong.cashier -ne 'Fartun Ali'){throw 'Wrong PIN caused a side effect or cashier swap.'}
  if($on.refund.cashier -ne 'Fartun Ali' -or $on.refund.approvedBy.name -ne 'Khadija Abdi'){throw 'Manager approval replaced or misattributed the cashier.'}
  if($on.reuse.status -ne 403 -or @($on.scope.psobject.Properties.Value.status | Where-Object {$_ -ne 403}).Count){throw 'Approval reuse/scope rejection failed.'}
  if($expired.status -ne 403 -or $expired.message -notmatch 'expired'){throw 'Expired approval was not rejected.'}
  if([math]::Abs([double]$on.cashOut.delta+13.6)-gt 0.001 -or $on.cashOut.cashier -ne 'Fartun Ali'){throw 'Protected refund/Cash Out reconciliation failed.'}
  if($on.domSecrets){throw 'Approval secret appeared in the DOM.'}
  $audit=& $mysql -uroot curdun_erp -N -e "SELECT action,user_id,record_id,new_values FROM audit_logs WHERE company_id=2 AND (action LIKE 'MANAGER_APPROVAL%' OR action IN ('ORDER_REFUND','CASH_OUT')) ORDER BY id DESC LIMIT 30"
  @{off=$off;denied=$denied;on=$on;expired=$expired;audit=$audit} | ConvertTo-Json -Depth 14
} finally {
  Set-ExtraSecurity $originalSetting
}
